-- Per-step tester comment: what the tester observed when a step has nothing to
-- attach as evidence (for example user names are generated by the system, so no
-- user name variant can be registered). Kept apart from step verdicts, so
-- resetting a step or a test keeps it, like evidence. An empty comment removes the row.
CREATE TABLE step_comments (
    target_id  INTEGER NOT NULL REFERENCES targets (id) ON DELETE CASCADE,
    test_id    TEXT    NOT NULL,
    step       INTEGER NOT NULL,
    comment    TEXT    NOT NULL,
    updated_at TEXT    NOT NULL,
    updated_by TEXT    NOT NULL,
    PRIMARY KEY (target_id, test_id, step)
);
